"""Editorial content for CC-10, Civil Code arts. 701-756."""
def row(says, means, example, warning, term, definition):
    return {"target": None, "o_que_diz": says, "o_que_significa": means, "exemplo_pratico": example, "atencao": warning, "palavras_dificeis": [{"termo": term, "explicacao": definition}]}

ROWS = {
    "701": row("Sem remuneração previamente definida, a comissão do intermediário é calculada conforme as práticas usuais do local.", "Os costumes do mercado suprem a ausência de cláusula sobre o valor devido ao comissário.", "Comissário vende mercadorias sem preço de remuneração ajustado; usa-se o percentual normalmente praticado na praça.", "A regra é subsidiária: prevalecem valor contratado e norma especial aplicável.", "Usos locais", "práticas reiteradas e reconhecidas no mercado de determinado lugar"),
    "702": row("Se o comissário morrer ou for impedido por força maior antes de terminar o negócio, o comitente paga valor proporcional ao trabalho realizado.", "A impossibilidade não elimina a remuneração já conquistada por atividade útil efetivamente prestada.", "Comissário inicia negociação e falece antes do fechamento; seu espólio recebe parcela correspondente ao serviço feito.", "A proporção depende da extensão e utilidade dos atos, e o impedimento precisa decorrer de força maior.", "Força maior", "evento inevitável que impede a conclusão da atividade"),
    "703": row("Mesmo quando provocou sua dispensa, o comissário recebe pelos serviços úteis, mas responde pelos prejuízos causados ao comitente.", "Remuneração pelo benefício produzido e indenização por conduta danosa são apuradas separadamente.", "Comissário obtém comprador, mas viola instrução e é dispensado; recebe pelo resultado útil e indeniza o dano comprovado.", "O pagamento não apaga a responsabilidade, e a indenização exige prejuízo e ligação causal.", "Serviço útil", "atividade que trouxe proveito verificável ao comitente"),
    "704": row("Em regra, o comitente pode modificar as instruções a qualquer momento, inclusive para negócios ainda pendentes.", "O comissário deve observar as orientações novas nos atos não concluídos, salvo cláusula que limite essa faculdade.", "Antes da venda ser fechada, o comitente eleva o preço mínimo e comunica o comissário.", "Alteração tardia não desfaz automaticamente negócio já concluído nem afasta despesas ou responsabilidades anteriores.", "Negócio pendente", "operação iniciada, mas ainda não definitivamente concluída"),
    "705": row("Dispensado sem causa legítima, o comissário recebe pelo trabalho feito e reparação pelos danos decorrentes da dispensa.", "A ruptura injustificada protege tanto a remuneração vencida quanto prejuízos adicionais demonstráveis.", "Comitente encerra imotivadamente a comissão após meses de atuação; paga serviços e investimentos perdidos comprovados.", "Perdas e danos não são automáticas em valor presumido; devem resultar da dispensa sem justa causa.", "Justa causa", "motivo grave que legitima o encerramento da relação"),
    "706": row("Há juros recíprocos: o comitente os paga sobre adiantamentos feitos pelo comissário; este os paga se atrasar a entrega de valores do comitente.", "A regra remunera capital empregado na execução das ordens e sanciona a retenção tardia de fundos alheios.", "Comissário antecipa frete e recebe reembolso com juros; se demora a repassar a venda, deve juros pelo atraso.", "É necessário distinguir adiantamento autorizado de despesa indevida e identificar o início da mora.", "Adiantamento", "valor antecipado para viabilizar o cumprimento da incumbência"),
    "707": row("Créditos do comissário por remuneração e despesas têm privilégio geral na insolvência ou falência do comitente.", "Na concorrência com credores, esses créditos recebem a preferência prevista para a categoria legal, sem vínculo com bem específico.", "Comitente insolvente deve comissão e reembolso; o comissário habilita os créditos com o privilégio correspondente.", "Privilégio geral não significa pagamento garantido nem preferência sobre todas as classes da legislação concursal.", "Privilégio geral", "preferência legal que alcança o patrimônio geral do devedor"),
    "708": row("O comissário pode reter bens e valores recebidos pela comissão até obter reembolso de despesas e pagamento de comissões.", "A retenção funciona como garantia ligada aos créditos surgidos da própria relação de comissão.", "Comissário conserva mercadorias do comitente enquanto permanece sem receber despesas justificadas e remuneração vencida.", "O direito não autoriza apropriação definitiva nem alcança automaticamente dívidas estranhas à comissão.", "Direito de retenção", "faculdade de conservar coisa alheia até o pagamento de crédito relacionado"),
    "709": row("As normas do mandato complementam o contrato de comissão quando forem compatíveis.", "Lacunas da comissão podem ser resolvidas pelo regime do mandato, respeitando a diferença de que o comissário atua em nome próprio.", "Questão de prestação de contas sem regra específica é examinada pelas disposições compatíveis do mandato.", "A remissão é subsidiária e não transforma o comissário em representante direto do comitente.", "Aplicação subsidiária", "uso complementar de outro conjunto de regras quando compatível"),
    "710": row("Agente promove negócios de forma contínua, remunerada, independente e em zona definida, por conta do proponente. Há distribuição quando dispõe da coisa negociada; podem existir poderes de representação.", "Agência organiza colaboração estável sem vínculo de dependência. Distribuição acrescenta disponibilidade material do produto, e representação exige poder específico.", "Empresa encarrega agente independente de promover vendas regionais; com estoque próprio para entrega, atua como distribuidor.", "Agência não se confunde automaticamente com emprego, mandato ou revenda; o vínculo depende dos elementos concretos.", "Agência", "contrato de promoção habitual de negócios por intermediário independente"),
    "711": row("Na falta de ajuste diferente, proponente e agente devem respeitar exclusividade recíproca na mesma zona e para negócios do mesmo gênero.", "O proponente não nomeia agente concorrente com incumbência idêntica, e o agente não atende concorrentes naquele espaço.", "Fabricante concede agência regional e não pode indicar segundo agente igual, enquanto o agente não promove marca concorrente.", "As partes podem afastar ou delimitar a exclusividade; zona, gênero e incumbência precisam estar identificados.", "Exclusividade recíproca", "restrição concorrencial que obriga ambos os lados do contrato"),
    "712": row("O agente deve executar a incumbência com diligência e seguir as instruções do proponente.", "A independência do agente não elimina o dever de cuidado nem a observância das orientações contratuais lícitas.", "Agente verifica dados do cliente e respeita a política de preços recebida do proponente.", "Instruções não podem alterar unilateralmente a natureza do contrato nem justificar conduta ilícita.", "Diligência", "cuidado e atenção esperados na execução profissional da incumbência"),
    "713": row("Salvo cláusula diversa, as despesas da agência ou distribuição são suportadas pelo próprio agente ou distribuidor.", "A remuneração ordinária pressupõe que o intermediário custeie sua estrutura, mas o contrato pode repartir gastos diferentemente.", "Agente paga viagens e escritório necessários à prospecção porque não houve acordo de reembolso.", "Despesa extraordinária solicitada pelo proponente deve ser examinada à luz do contrato e das instruções dadas.", "Despesa operacional", "gasto necessário ao funcionamento habitual da atividade"),
    "714": row("Em regra, o agente ou distribuidor recebe pelos negócios fechados em sua zona, mesmo sem participação direta.", "A exclusividade territorial vincula a remuneração ao resultado econômico ocorrido na área atribuída.", "Cliente da zona compra diretamente do proponente; o agente conserva a comissão, salvo ajuste diferente.", "É preciso provar que o negócio pertence à zona e ao objeto contratual; cláusula diversa pode modificar a regra.", "Remuneração territorial", "comissão ligada aos negócios realizados dentro da área atribuída"),
    "715": row("O intermediário tem direito a indenização quando o proponente, sem justa causa, interrompe ou reduz propostas a ponto de tornar o contrato antieconômico.", "A conduta do proponente não pode esvaziar injustificadamente a atividade e transferir ao agente o custo de uma relação inviável.", "Fornecedor corta quase todo o abastecimento regional sem motivo e inviabiliza a distribuidora.", "A queda deve ser relevante e imputável ao proponente; oscilações normais do mercado não bastam.", "Antieconômico", "incapaz de sustentar racionalmente os custos da atividade"),
    "716": row("O agente recebe remuneração quando o negócio deixa de ocorrer por fato atribuível ao proponente.", "Quem frustra a operação não pode retirar do agente a comissão que seria devida pelo trabalho realizado.", "Agente obtém pedido válido, mas o proponente recusa entrega sem justificativa; a remuneração permanece devida.", "É necessário demonstrar o nexo entre a conduta do proponente e a não conclusão do negócio.", "Fato imputável", "acontecimento juridicamente atribuído à conduta de uma parte"),
    "717": row("Mesmo dispensado por justa causa, o agente recebe pelos serviços úteis, sem impedir que o proponente cobre seus prejuízos.", "O benefício já produzido é remunerado, enquanto a falta do agente pode gerar responsabilidade separada.", "Agente conclui vendas úteis, mas comete infração grave; recebe pelas vendas e indeniza o dano causado.", "A compensação entre valores depende da apuração dos créditos e não autoriza punição superior ao prejuízo.", "Dispensa por justa causa", "encerramento motivado por inadimplemento grave do agente"),
    "718": row("Dispensa sem culpa do agente assegura remuneração vencida, comissão sobre negócios pendentes e indenizações previstas em lei especial.", "A ruptura imotivada não elimina resultados em formação nem proteções externas aplicáveis à atividade.", "Proponente encerra a agência sem falta do intermediário enquanto pedidos captados aguardam conclusão.", "A indenização especial pertence à camada legislativa externa e exige conferir seus requisitos próprios.", "Negócio pendente", "operação encaminhada durante o contrato e ainda não concluída"),
    "719": row("Impedido por força maior, o agente recebe proporcionalmente pelos serviços realizados; se morrer, o direito passa aos herdeiros.", "A impossibilidade inevitável encerra a atividade sem apagar a remuneração adquirida pelo trabalho útil.", "Agente adoece gravemente após executar parte da campanha; recebe parcela correspondente, transmitida aos herdeiros se falecer.", "O valor depende do serviço efetivo, e a força maior deve realmente impedir a continuidade.", "Remuneração proporcional", "pagamento calculado segundo a parcela de trabalho cumprida"),
    "720": row("Contrato de agência sem prazo pode ser encerrado por qualquer parte com aviso de noventa dias, após tempo compatível com o investimento exigido. Divergências podem ser decididas judicialmente.", "O aviso protege a recuperação razoável de investimentos e evita ruptura súbita de relação duradoura.", "Agente monta estrutura regional; após período adequado, o proponente comunica a saída com noventa dias.", "O prazo fixo de aviso não dispensa avaliar se o investimento teve tempo razoável de retorno.", "Aviso prévio", "comunicação antecipada do encerramento de contrato continuado"),
    "721": row("Agência e distribuição recebem, quando compatíveis, regras do mandato, da comissão e de legislação especial.", "O regime contratual é integrado por normas complementares sem apagar suas características próprias.", "Questão de prestação de contas é resolvida por regra compatível do mandato, além da lei especial da categoria.", "A aplicação depende de compatibilidade; não se presume representação nem vínculo trabalhista.", "Integração normativa", "combinação de regras de diferentes diplomas para completar um regime"),
    "722": row("Corretagem é a mediação independente pela qual alguém busca um ou mais negócios para o cliente, conforme instruções, sem mandato, emprego ou prestação de serviço subordinada.", "O corretor aproxima interessados e procura o resultado ajustado, mas não representa necessariamente qualquer parte.", "Corretor localiza comprador para imóvel segundo preço e condições indicados pelo proprietário.", "A qualificação depende da autonomia e da ausência dos vínculos excluídos pela norma.", "Mediação", "atividade de aproximar partes para possibilitar a celebração de negócio"),
    "723": row("O corretor deve agir com prudência e diligência, informar espontaneamente o andamento e esclarecer riscos, segurança, variações de valor e fatores relevantes, sob responsabilidade por danos.", "O dever de informação é ativo: o cliente não precisa perguntar sobre elementos que podem influir na decisão.", "Corretor alerta comprador sobre alteração de preço e risco documental descoberto durante a negociação.", "Responsabilidade exige violação do dever, prejuízo e nexo; o corretor não garante todo resultado do negócio.", "Dever de informação", "obrigação de revelar dados relevantes para decisão consciente do cliente"),
    "724": row("Se lei e contrato não fixarem a remuneração do corretor, o valor será definido pela natureza do negócio e pelos usos locais.", "A ausência de preço não torna gratuito o serviço; critérios objetivos do mercado completam o contrato.", "Corretagem de operação incomum é remunerada conforme complexidade e prática da região.", "Norma especial ou tabela legal prevalece sobre o arbitramento subsidiário.", "Arbitramento", "fixação do valor devido por critérios jurídicos e econômicos"),
    "725": row("A corretagem é devida quando o corretor alcança o resultado contratado, inclusive se o negócio não se efetiva por arrependimento das partes.", "Obtido o consenso ou resultado útil definido, desistência posterior não elimina a remuneração.", "Corretor aproxima comprador e vendedor que acordam condições, mas depois desistem; a comissão pode ser exigida.", "É essencial identificar qual resultado o contrato definiu e se ele foi efetivamente alcançado.", "Resultado útil", "evento contratualmente previsto que faz nascer a remuneração"),
    "726": row("Negócio fechado diretamente não gera comissão, salvo corretagem exclusiva por escrito; nessa hipótese, a remuneração integral subsiste, exceto se o corretor ficou inerte ou ocioso.", "A exclusividade escrita protege o intermediário, mas exige atuação minimamente diligente.", "Proprietário com corretor exclusivo vende sozinho e paga comissão, a menos que prove completa inércia do profissional.", "Exclusividade verbal não produz o efeito especial, e a inércia deve ser comprovada.", "Corretagem exclusiva", "ajuste escrito que reserva a mediação a determinado corretor"),
    "727": row("Mesmo após dispensa ou fim do prazo, a comissão é devida se o negócio posterior resultar do trabalho do corretor.", "O nexo causal entre mediação e conclusão impede que o cliente evite pagamento apenas esperando o contrato terminar.", "Comprador apresentado pelo corretor fecha a compra após a dispensa; o profissional recebe a comissão.", "A mera realização posterior não basta: deve ser fruto efetivo da mediação anterior.", "Nexo causal", "ligação entre o trabalho do corretor e o negócio concluído"),
    "728": row("Quando vários corretores participam da conclusão, dividem a remuneração igualmente, salvo ajuste diferente.", "A colaboração gera rateio padrão, que pode ser alterado por acordo válido.", "Dois corretores atuam conjuntamente e repartem a comissão pela metade na ausência de cláusula específica.", "Só participa do rateio quem efetivamente intermediou; o contrato pode fixar percentuais distintos.", "Rateio", "divisão de valor entre pessoas com direito comum"),
    "729": row("As regras civis de corretagem convivem com normas especiais aplicáveis à atividade ou ao negócio.", "O Código fornece regime geral, mas habilitação, disciplina profissional e setores regulados podem impor exigências adicionais.", "Corretagem imobiliária observa o Código Civil e também a legislação profissional específica.", "A norma especial não deve ser presumida; é preciso identificar seu âmbito e vigência.", "Legislação especial", "conjunto de regras voltado a setor ou situação específica"),
    "730": row("No transporte remunerado, o transportador assume levar pessoas ou coisas de um local a outro.", "Deslocamento, destino e contraprestação formam o núcleo do contrato, com deveres próprios de segurança e entrega.", "Empresa recebe frete para conduzir carga entre duas cidades.", "Transporte gratuito por cortesia pode seguir regime diferente, e serviços públicos também têm regras próprias.", "Transportador", "parte que assume contratualmente o deslocamento de pessoa ou coisa"),
    "731": row("Transporte prestado por autorização, permissão ou concessão segue a regulamentação e os atos administrativos correspondentes, além do Código Civil.", "O regime público ou regulado complementa as obrigações contratuais gerais.", "Empresa concessionária de ônibus observa contrato de concessão, regulamento setorial e normas civis.", "O Código não afasta tarifas, padrões de serviço e deveres estabelecidos pelo poder público.", "Concessão", "delegação contratual de serviço público a particular"),
    "732": row("Legislação especial e tratados internacionais complementam o transporte quando compatíveis com o Código Civil.", "A solução jurídica pode exigir normas setoriais ou internacionais, desde que não contrariem o regime civil aplicável.", "Transporte internacional de carga é examinado também conforme convenção incorporada ao direito brasileiro.", "A incidência externa depende do tipo, percurso e âmbito do transporte; não é automática em toda operação.", "Tratado internacional", "acordo entre Estados incorporado ao ordenamento conforme o procedimento constitucional"),
    "733": row("No transporte cumulativo, cada transportador responde por seu trecho. Atraso ou interrupção considera o percurso total, e substituto integra a solidariedade quando houver troca no caminho.", "A divisão operacional não deixa o usuário sem proteção, mas permite apurar onde ocorreu o dano.", "Carga percorre três trechos; avaria no segundo gera responsabilidade do respectivo transportador, observada a solidariedade aplicável.", "Responsabilidade perante o usuário e acerto interno entre transportadores são planos distintos.", "Transporte cumulativo", "viagem executada sucessivamente por mais de um transportador"),
    "734": row("O transportador responde por danos ao passageiro e à bagagem, salvo força maior; cláusula que exclua essa responsabilidade é nula. Pode exigir declaração do valor da bagagem para limitar indenização.", "O dever de segurança não pode ser afastado por contrato, embora o valor declarado possa delimitar a reparação da bagagem.", "Passageiro sofre dano durante viagem e cobra reparação; mala declarada tem limite vinculado ao valor informado.", "A exceção exige força maior comprovada, e declaração de valor não elimina responsabilidade por outros danos.", "Cláusula excludente", "disposição que tenta afastar previamente responsabilidade legal"),
    "735": row("Culpa de terceiro não afasta a responsabilidade contratual do transportador perante o passageiro; depois de indenizar, ele pode cobrar do responsável.", "O passageiro dirige sua pretensão ao transportador, que preserva ação regressiva contra quem causou o acidente.", "Ônibus é atingido por outro veículo; a empresa indeniza passageiro e busca ressarcimento do motorista culpado.", "A regra não impede apuração de força maior nem eventual contribuição da própria vítima.", "Ação regressiva", "cobrança contra quem deve suportar definitivamente o prejuízo pago por outro"),
    "736": row("Transporte gratuito por amizade ou cortesia não segue o regime contratual de transporte; se houver vantagem indireta para o transportador, não é considerado gratuito.", "A gratuidade real exige ausência de benefício econômico, ainda que não exista pagamento em dinheiro.", "Amigo oferece carona sem qualquer vantagem; situação difere de transporte gratuito usado para atrair clientes.", "A qualificação depende das circunstâncias, não apenas da inexistência de tarifa.", "Vantagem indireta", "benefício econômico ou comercial recebido sem pagamento direto"),
    "737": row("O transportador deve cumprir horários e itinerários e indeniza danos pelo descumprimento, salvo força maior.", "Pontualidade e rota integram a prestação contratada, mas evento inevitável pode afastar responsabilidade.", "Empresa altera injustificadamente o percurso e faz passageiro perder conexão comprovada.", "A indenização exige dano e nexo; atraso irrelevante não gera automaticamente qualquer reparação.", "Itinerário", "trajeto previsto para execução do transporte"),
    "738": row("Passageiro deve seguir regras visíveis ou constantes do bilhete e não prejudicar pessoas, veículo ou serviço. Se sua infração contribuir para o próprio dano, a indenização será reduzida proporcionalmente.", "O dever de cooperação do usuário permite repartir consequências quando sua conduta participa do resultado.", "Passageiro ignora instrução de segurança e agrava lesão; o juiz reduz a reparação conforme sua contribuição.", "Redução exige relação causal e medida equitativa, não perda automática de todo o direito.", "Culpa concorrente", "participação da própria vítima na produção ou agravamento do dano"),
    "739": row("O transportador deve aceitar passageiros, salvo restrição regulamentar ou condição de higiene ou saúde que justifique a recusa.", "A oferta de transporte não permite seleção arbitrária, mas admite exceções objetivas ligadas à segurança e regulação.", "Embarque é recusado quando condição sanitária concreta cria risco previsto no regulamento.", "A exceção não autoriza discriminação; o motivo deve ser legítimo, proporcional e demonstrável.", "Recusa justificada", "negação do serviço apoiada em fundamento legal e objetivo"),
    "740": row("Antes da viagem, o passageiro pode desistir e receber o preço se houver tempo para revenda. Após o início ou em caso de não embarque, reembolso depende de substituição por outra pessoa; pode haver retenção de até cinco por cento.", "O equilíbrio considera a possibilidade de o transportador reutilizar o lugar e admite multa compensatória limitada.", "Passageiro avisa cedo e recebe o valor menos retenção permitida.", "Cada hipótese tem requisito próprio; ausência de comunicação ou de substituição pode afastar reembolso.", "Multa compensatória", "parcela retida para compensar custos da desistência"),
    "741": row("Interrompida a viagem por causa alheia ao transportador, ele deve concluir o percurso em veículo equivalente ou, com consentimento, por outro meio, pagando também estadia e alimentação durante a espera.", "Mesmo sem culpa, permanece o dever de assegurar continuidade e assistência ao passageiro.", "Pane causada por evento imprevisível exige ônibus substituto e custeio da alimentação na espera.", "Modalidade diferente depende de anuência, e as despesas devem guardar relação com a interrupção.", "Assistência material", "apoio de transporte, alimentação e estadia durante a interrupção"),
    "742": row("Depois de realizar o transporte, o transportador pode reter bagagem e objetos pessoais para garantir passagem ainda não paga.", "A retenção assegura crédito diretamente ligado ao serviço já prestado.", "Passageiro chega ao destino sem pagar e a empresa conserva a mala até a quitação.", "Não há autorização para apropriar-se dos bens, e a medida deve ser proporcional ao débito.", "Retenção", "conservação temporária de bem alheio como garantia de pagamento"),
    "743": row("A carga entregue deve ser identificada por natureza, valor, peso, quantidade e outros dados necessários, com nome e endereço do destinatário.", "A individualização evita confusão e permite ao transportador planejar guarda, percurso e entrega.", "Remetente declara vinte caixas, peso, conteúdo, valor e endereço de quem receberá.", "Informação incompleta ou falsa pode gerar responsabilidade e comprometer limites indenizatórios.", "Caracterização da carga", "conjunto de dados que individualiza a coisa transportada"),
    "744": row("Ao receber a carga, o transportador emite conhecimento com seus dados identificadores, observando lei especial. Pode exigir relação assinada em duas vias, integrando uma delas ao documento.", "O conhecimento registra recebimento e condições essenciais, servindo à circulação e à prova da operação.", "Transportadora autentica lista detalhada das mercadorias e a anexa ao conhecimento.", "O documento não dispensa exigências fiscais, regulatórias ou setoriais externas.", "Conhecimento de transporte", "documento que registra a carga recebida e as condições do transporte"),
    "745": row("Descrição falsa ou inexata permite ao transportador cobrar o prejuízo, mas a ação deve ser proposta em cento e vinte dias a partir do ato, sob decadência.", "O remetente responde pela informação defeituosa e o prazo curto extingue o direito de reclamar se não observado.", "Peso declarado incorretamente causa multa à transportadora, que ajuíza cobrança dentro de cento e vinte dias.", "Devem ser provados falsidade ou inexatidão, dano e nexo; o prazo é decadencial.", "Decadência", "extinção do direito pelo não exercício no prazo legal"),
    "746": row("O transportador pode recusar embalagem inadequada ou carga capaz de ameaçar pessoas, veículo ou outros bens.", "A recusa facultativa protege a segurança e a integridade da operação antes da aceitação do risco.", "Transportadora rejeita recipiente frágil com produto que pode vazar e danificar outras cargas.", "A avaliação deve ser objetiva; embalagem reparável pode permitir adequação antes do transporte.", "Embalagem inadequada", "acondicionamento insuficiente para transporte seguro"),
    "747": row("O transportador deve recusar carga proibida ou desacompanhada dos documentos exigidos.", "Diferentemente da faculdade do artigo anterior, aqui a recusa é obrigatória por ilicitude ou irregularidade documental.", "Mercadoria controlada sem licença legal não pode ser aceita para transporte.", "A obrigação exige verificar proibição e documentação pertinente ao tipo de carga.", "Recusa obrigatória", "dever legal de não aceitar determinada carga"),
    "748": row("Antes da entrega, o remetente pode cancelar o transporte, pedir a carga de volta ou mudar o destinatário, pagando despesas adicionais e danos decorrentes da contraordem.", "O poder de redirecionamento permanece enquanto a entrega não ocorreu, mas seus custos não recaem sobre o transportador.", "Remetente muda o destino após a partida e paga desvio, armazenagem e prejuízo comprovado.", "A ordem deve ser possível e legítima, sem prejudicar direitos já constituídos do destinatário.", "Contraordem", "nova instrução que altera ou cancela a ordem original de transporte"),
    "749": row("O transportador deve levar a carga ao destino, conservá-la adequadamente e entregá-la no prazo contratado ou previsto.", "Custódia, deslocamento e pontualidade formam deveres centrais do transporte de coisas.", "Empresa protege produto sensível durante o percurso e o entrega na data ajustada.", "O padrão de cautela depende da natureza declarada da carga e das condições conhecidas.", "Dever de conservação", "obrigação de proteger a coisa contra perda e deterioração"),
    "750": row("A responsabilidade, limitada ao valor indicado no conhecimento, começa com o recebimento da carga e termina na entrega ou no depósito judicial se o destinatário não for localizado.", "A lei define período de custódia e referência econômica para a responsabilidade do transportador.", "Carga avaliada no conhecimento é avariada após coleta; a transportadora responde dentro do regime legal.", "Limitação não protege fraude ou outras situações afastadas por normas aplicáveis; o depósito deve ser legítimo.", "Período de responsabilidade", "intervalo em que o transportador responde pela carga recebida"),
    "751": row("Carga guardada nos armazéns do transportador por causa do transporte segue, quando compatíveis, as regras do depósito.", "Durante a armazenagem, deveres de guarda e restituição complementam o regime de transporte.", "Mercadoria aguarda conexão no depósito da transportadora e recebe proteção própria do depósito.", "A aplicação é compatível e subsidiária; não encerra necessariamente o contrato de transporte.", "Depósito", "relação de guarda de coisa alheia com dever de restituição"),
    "752": row("Após o desembarque, aviso ao destinatário e entrega em domicílio só são obrigatórios se ajustados e registrados no conhecimento.", "Esses serviços adicionais não se presumem e precisam constar do documento de transporte.", "Conhecimento prevê aviso eletrônico e entrega no endereço; a transportadora deve cumpri-los.", "Leis ou regulamentos especiais podem impor deveres adicionais independentemente do ajuste.", "Entrega a domicílio", "serviço de levar a carga até o endereço final do destinatário"),
    "753": row("Impossibilidade ou longa interrupção exige instruções imediatas ao remetente e cuidado com a carga. Persistindo o impedimento, cabem depósito ou venda em condições legais, com informação ao remetente; guarda própria gera dever e remuneração.", "A norma organiza alternativas para preservar valor e definir custos conforme a causa do impedimento.", "Estrada fecha por longo período; transportador consulta remetente e deposita carga não perecível, comunicando a medida.", "Venda é excepcional, especialmente se o impedimento for imputável ao transportador, quando só cabe para perecíveis.", "Depósito judicial", "entrega da coisa à custódia determinada ou reconhecida judicialmente"),
    "754": row("O destinatário ou portador do conhecimento endossado deve conferir a carga e reclamar ao recebê-la. Dano parcial oculto pode ser denunciado em dez dias; sem isso, ocorre decadência.", "A inspeção imediata preserva prova, enquanto avaria não aparente recebe prazo específico.", "Destinatário descobre dano interno três dias depois e comunica formalmente a transportadora.", "O prazo especial trata de perda parcial ou avaria não perceptível, não de toda controvérsia contratual.", "Avaria oculta", "dano na carga que não é perceptível no exame inicial"),
    "755": row("Havendo dúvida sobre o destinatário e faltando instrução, o transportador deposita a carga judicialmente; se a demora ameaçar deterioração, deve vendê-la e depositar o saldo.", "A medida evita entrega indevida e preserva o valor econômico de bem perecível.", "Dois sujeitos disputam a carga refrigerada; a transportadora promove venda e deposita o resultado.", "Venda exige risco de deterioração e prestação de contas do saldo, não autorização para apropriação.", "Saldo", "valor restante após dedução legítima das despesas"),
    "756": row("No transporte cumulativo, todos respondem solidariamente perante o remetente; depois, o custo é atribuído integral ou proporcionalmente a quem causou o dano em seu trecho.", "A solidariedade facilita a reparação externa e a apuração interna distribui a responsabilidade final.", "Carga passa por três transportadores e chega avariada; o remetente cobra qualquer deles, que ajustam o ressarcimento entre si.", "O regresso depende da identificação do trecho e da contribuição de cada transportador.", "Responsabilidade solidária", "possibilidade de cobrar a dívida integral de qualquer responsável"),
}
